import json,pathlib,re,hashlib,collections
ROOT=pathlib.Path(__file__).resolve().parent
load=lambda p:json.load(open(ROOT/p))
def save(p,x):(ROOT/p).write_text(json.dumps(x,indent=2))
def matrix(q):return [r.split('&') for r in re.search(r'\\begin\{bmatrix\}(.*?)\\end\{bmatrix\}',q[':question/problem'],re.S)[1].split('\\\\')]
def shape(q):m=matrix(q);return (len(m),len(m[0]))
def counts(records):return dict(collections.Counter(f'{shape(r["question"])[0]}x{shape(r["question"])[1]}' for r in records))
